def link_approved(apps, schema_editor):
    """Days fixed by an approved correction before regularization existed get the "Regularized" tag too."""
    Correction = apps.get_model("hr", "AttendanceCorrection")
    Attendance = apps.get_model("hr", "Attendance")
    for c in Correction.objects.filter(status="approved").order_by("created_at"):
        Attendance.objects.filter(user_id=c.user_id, date=c.date).update(regularization=c)


